CREATE TABLE tagged (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT tagged_pkey PRIMARY KEY (id)
);

CREATE TABLE tagged_book (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  tagged_id UUID NOT NULL,
  book_id UUID NOT NULL,
  CONSTRAINT tagged_book_pkey PRIMARY KEY (id),
  CONSTRAINT tagged_book_tagged_id_fkey FOREIGN KEY (tagged_id) REFERENCES tagged (id) ON DELETE CASCADE,
  CONSTRAINT tagged_book_book_id_fkey FOREIGN KEY (book_id) REFERENCES book (id) ON DELETE CASCADE
